package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Simple integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Positive sign", NumberUtils.isNumber("+123"));
        assertFalse("Only sign", NumberUtils.isNumber("-"));
        assertFalse("Only sign plus", NumberUtils.isNumber("+"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Trailing dot", NumberUtils.isNumber("123."));
        assertTrue("Dot with digit", NumberUtils.isNumber(".123")); // Note: implementation requires foundDigit check logic
        assertTrue("Decimal with sign", NumberUtils.isNumber("-123.45"));
        assertFalse("Two dots", NumberUtils.isNumber("123.45.67"));
        assertFalse("Dot in exponent", NumberUtils.isNumber("1e2.3"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hex lowercase", NumberUtils.isNumber("0x1a2b"));
        assertTrue("Hex uppercase", NumberUtils.isNumber("0x1A2B"));
        assertTrue("Hex with negative", NumberUtils.isNumber("-0x123"));
        assertTrue("Hex with digits only", NumberUtils.isNumber("0x123"));
        assertFalse("Hex empty suffix", NumberUtils.isNumber("0x"));
        assertFalse("Hex invalid char", NumberUtils.isNumber("0x1z"));
        assertFalse("Hex non-hex char", NumberUtils.isNumber("0xG"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Scientific e", NumberUtils.isNumber("123e45"));
        assertTrue("Scientific E", NumberUtils.isNumber("123E45"));
        assertTrue("Scientific negative exponent", NumberUtils.isNumber("123e-45"));
        assertTrue("Scientific positive exponent", NumberUtils.isNumber("123e+45"));
        assertTrue("Scientific decimal", NumberUtils.isNumber("123.45e10"));
        assertFalse("No digit before E", NumberUtils.isNumber("e10"));
        assertFalse("No digit after E", NumberUtils.isNumber("123e"));
        assertFalse("No digit after E sign", NumberUtils.isNumber("123e-"));
        assertFalse("Two Es", NumberUtils.isNumber("123e45e67"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // Testing d, D, f, F (allowed if foundDigit is true)
        assertTrue("Double suffix d", NumberUtils.isNumber("123d"));
        assertTrue("Double suffix D", NumberUtils.isNumber("123D"));
        assertTrue("Float suffix f", NumberUtils.isNumber("123f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123F"));

        // Testing l, L (allowed only if no exp and no dec)
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));
        assertFalse("Long with decimal", NumberUtils.isNumber("123.4l"));
        assertFalse("Long with exponent", NumberUtils.isNumber("123e4l"));

        // Invalid suffixes
        assertFalse("Invalid suffix x", NumberUtils.isNumber("123x"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse("String with spaces", NumberUtils.isNumber(" 123 "));
        assertFalse("String with letters", NumberUtils.isNumber("123a"));
        assertFalse("Mixed hex and decimal", NumberUtils.isNumber("0x12.3"));
        // Testing specifically the end of method logic: return !allowSigns && foundDigit;
        // If we have "123e+", allowSigns is true, foundDigit is false (reset by sign)
        // Wait, if "123e+", i reaches end, allowSigns=true, foundDigit=false -> returns false.
        assertFalse("Trailing E sign", NumberUtils.isNumber("123e+"));
    }
}
